  function savePrefs(){try{const controls={};['Search','Section','Workstream','Owner','Country','Customer','Status','Rag','Ball','Due','Directive'].forEach(k=>{const n=$('#majorTask'+k+(k==='Search'?'':'Filter'));if(n)controls[k]=n.value});ui.savedControls=controls;localStorage.setItem(STORE,JSON.stringify({view:ui.view,filters:ui.filters,controls,summaryFilter:ui.summaryFilter}))}catch(_e){}}
