    Object.entries(ui.savedControls).forEach(([k,v])=>{const n=$('#majorTask'+k+(k==='Search'?'':'Filter'));if(!n)return;if(n.tagName==='INPUT'||Array.from(n.options||[]).some(o=>o.value===v))n.value=v});renderSubFilters();renderViewButtons();
