  function query(){const p=new URLSearchParams({page:String(ui.page),per_page:'30'});const map={search:'#majorTaskSearch',section:'#majorTaskSectionFilter',workstream:'#majorTaskWorkstreamFilter',owner:'#majorTaskOwnerFilter',country:'#majorTaskCountryFilter',customer:'#majorTaskCustomerFilter',status:'#majorTaskStatusFilter',rag:'#majorTaskRagFilter',ball:'#majorTaskBallFilter',directive:'#majorTaskDirectiveFilter'};Object.entries(map).forEach(([k,s])=>{const v=$(s)?.value;if(v)p.set(k,v)});const due=$('#majorTaskDueFilter')?.value;if(due)p.set(due,'1');if(ui.filters.business.length)p.set('business',ui.filters.business.join(','));if(ui.filters.subcategory.length)p.set('subcategory',ui.filters.subcategory.join(','));if(ui.view==='archive')p.set('archive','1');if(ui.view==='list'){p.set('hierarchy','root');p.set('include_children','1')}if(ui.summaryFilter==='mine')p.set('mine','1');if(ui.summaryFilter==='red'||ui.summaryFilter==='amber')p.set('rag',ui.summaryFilter);if(ui.summaryFilter==='directive')p.set('directive','1');if(ui.summaryFilter==='internal_ball')p.set('ball','internal');if(ui.summaryFilter==='external_wait')p.set('ball','external');if(ui.summaryFilter==='follow_up_due')p.set('followup','1');if(ui.summaryFilter==='overdue')p.set('overdue','1');if(ui.summaryFilter==='week_due')p.set('week_due','1');if(ui.summaryFilter==='decision_needed')p.set('decision','1');if(ui.summaryFilter==='blocked')p.set('blocker','1');return p}
