  function stageFields(s={}){return `<input name="version" type="hidden" value="${s?.version||''}"><label class="full">Stage 이름<input name="name" required value="${esc(s?.name||'')}"></label><label>상태<select name="status">${[['planned','예정'],['active','진행'],['completed','완료']].map(([v,l])=>`<option value="${v}" ${s?.status===v?'selected':''}>${l}</option>`).join('')}</select></label><div class="full"><span class="form-label">Stage 담당자 · 복수선택</span><div id="majorQuickStageAssignees" class="major-people-picker"></div></div><label>목표일<input name="target_date" type="date" value="${esc(s?.target_date||'')}"></label><label>시작일<input name="started_at" type="date" value="${esc(s?.started_at||'')}"></label><label>완료일<input name="completed_at" type="date" value="${esc(s?.completed_at||'')}"></label><label class="check-field"><input name="is_current" type="checkbox" ${s?.is_current?'checked':''}><span>Current Stage로 지정</span></label><label class="full">메모<textarea name="note">${esc(s?.note||'')}</textarea></label>`}
  function milestoneFields(m={},choices=[]){return `<input name="version" type="hidden" value="${m?.version||''}"><label class="full">마일스톤명<input name="name" required value="${esc(m?.name||'')}"></label><label>상태<select name="status">${[['not_started','미착수'],['in_progress','진행중'],['waiting','대기'],['completed','완료'],['cancelled','취소']].map(([v,l])=>`<option value="${v}" ${m?.status===v?'selected':''}>${l}</option>`).join('')}</select></label><label>담당자<select name="owner_id">${userOptions(m?.owner_id)}</select></label><label>부담당자<select name="deputy_owner_id">${userOptions(m?.deputy_owner_id)}</select></label><label>예정 시작일<input name="planned_start_date" type="date" value="${esc(m?.planned_start_date||'')}"></label><label>예정 완료일<input name="planned_end_date" type="date" value="${esc(m?.planned_end_date||'')}"></label><label>실제 완료일<input name="actual_completion_date" type="date" value="${esc(m?.actual_completion_date||'')}"></label><label>선행 마일스톤<select name="predecessors" multiple size="4">${selectOptions(choices,m?.predecessors)}</select></label><label class="check-field"><input name="is_required" type="checkbox" ${m?.is_required===false?'':'checked'}><span>필수 마일스톤</span></label><label class="full">선행 미완료 시작 사유<input name="override_reason" value="${esc(m?.started_with_override_reason||'')}"></label><label class="full">설명<textarea name="description">${esc(m?.description||'')}</textarea></label><label class="full">결과<textarea name="result">${esc(m?.result||'')}</textarea></label>`}
